import java.util.*;
public class Main {
    static long hoursNeeded(int[] piles, int speed) {
        long hours = 0;
        for (int pile : piles) {
            hours += pile / speed;
        }
        return hours;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        int[] piles = new int[n];
        int high = 0;
        for (int i = 0; i < n; i++) {
            piles[i] = sc.nextInt();
            high = Math.max(high, piles[i]);
        }
        int low = 1;
        int answer = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (hoursNeeded(piles, mid) <= h) {
                answer = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
